class Box<T>{private T value;Box(T v){value=v;}void setValue(T v){value=v;}T getValue(){return value;}}public class Q5_Generic_Storage_Class{public static void main(String[]x){Box<Integer>a=new Box<>(10);Box<String>b=new Box<>("Java");Box<Double>c=new Box<>(12.5);System.out.println(a.getValue());System.out.println(b.getValue());System.out.println(c.getValue());a.setValue(20);System.out.println(a.getValue());}}
